function initCmykControls(){$$('input[type="color"]').forEach(target=>{if(CMYK_WIDGETS.has(target.id))return;target.classList.add('cmyk-native');target.disabled=true;const wrapper=document.createElement('div');wrapper.className='cmyk-control cmyk-compact';wrapper.innerHTML='<button class="cmyk-chip" type="button" aria-label="색상 피커 열기" aria-haspopup="dialog" title="클릭해서 색상 선택"><span aria-hidden="true">⌄</span></button>';target.after(wrapper);const w={target,chip:wrapper.querySelector('.cmyk-chip')};CMYK_WIDGETS.set(target.id,w);w.chip.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();openColorPicker(target.id);});syncCmykControl(target.id);});}
function syncAllCmyk(){for(const id of CMYK_WIDGETS.keys())syncCmykControl(id);}
function rgbaTileToCmyk(rgba,palette={}){const out=new Uint8Array(rgba.length),cache=new Map();for(const [hex,v] of Object.entries(palette))cache.set(parseInt(hex.slice(1),16),v.map(n=>Math.round(n/100*255)));for(let i=0;i<rgba.length;i+=4){const a=rgba[i+3]/255,r=Math.round(rgba[i]*a+255*(1-a)),g=Math.round(rgba[i+1]*a+255*(1-a)),b=Math.round(rgba[i+2]*a+255*(1-a)),key=(r<<16)|(g<<8)|b,known=cache.get(key);if(known){out.set(known,i);continue;}const max=Math.max(r,g,b);out[i]=max?Math.round((max-r)/max*255):0;out[i+1]=max?Math.round((max-g)/max*255):0;out[i+2]=max?Math.round((max-b)/max*255):0;out[i+3]=255-max;}return out;}
function makeCmykPdfBytes(compressed,widthPx,heightPx,widthMm,heightMm,bleed=false){const enc=new TextEncoder(),parts=[],offsets=[0];let length=0;const push=v=>{const b=typeof v==='string'?enc.encode(v):v;parts.push(b);length+=b.length;},pt=v=>(v/25.4*72).toFixed(5),W=pt(widthMm),H=pt(heightMm);push('%PDF-1.7\n%WORKUP-CMYK\n');const obj=(n,body)=>{offsets[n]=length;push(n+' 0 obj\n'+body+'\nendobj\n');};obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');const boxes=bleed?' /TrimBox ['+pt(8)+' '+pt(8)+' '+pt(widthMm-8)+' '+pt(heightMm-8)+'] /BleedBox ['+pt(5)+' '+pt(5)+' '+pt(widthMm-5)+' '+pt(heightMm-5)+']':'';obj(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+W+' '+H+']'+boxes+' /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>');offsets[4]=length;push('4 0 obj\n<< /Type /XObject /Subtype /Image /Width '+widthPx+' /Height '+heightPx+' /ColorSpace /DeviceCMYK /BitsPerComponent 8 /Filter /FlateDecode /Interpolate false /Length '+compressed.length+' >>\nstream\n');push(compressed);push('\nendstream\nendobj\n');const content='q\n'+W+' 0 0 '+H+' 0 0 cm\n/Im0 Do\nQ\n';obj(5,'<< /Length '+enc.encode(content).length+' >>\nstream\n'+content+'endstream');obj(6,'<< /Title (WORKUP Print Studio CMYK) /Producer (WORKUP CMYK Raster Export) >>');const xref=length;push('xref\n0 7\n0000000000 65535 f \n');for(let i=1;i<=6;i++)push(String(offsets[i]).padStart(10,'0')+' 00000 n \n');push('trailer\n<< /Size 7 /Root 1 0 R /Info 6 0 R >>\nstartxref\n'+xref+'\n%%EOF\n');const result=new Uint8Array(length);let p=0;for(const b of parts){result.set(b,p);p+=b.length;}return result;}
async function exportCmykPdf(){const btn=$('saveCmykPdf'),status=$('cmykProgress');btn.disabled=true;let canvas,url;try{if(typeof CompressionStream==='undefined')throw Error('CMYK PDF는 최신 크롬 또는 엣지에서 저장해 주세요.');const bleed=printConfig().cropMarks,dpi=Number($('cmykDpi').value)||300,w=state.width+(bleed?16:0),h=state.height+(bleed?16:0),pw=Math.round(w/25.4*dpi),ph=Math.round(h/25.4*dpi);if(pw*ph>90000000)throw Error('이 크기는 메모리를 많이 사용합니다. 150dpi를 선택하거나 용지를 줄여 주세요.');status.textContent='폰트와 이미지를 준비하고 있어요…';await document.fonts.ready;let fontFace='';for(const sheet of document.styleSheets){try{for(const rule of sheet.cssRules)if(rule.cssText.startsWith('@font-face')&&rule.cssText.includes('Pretendard')){fontFace=rule.cssText;break;}}catch{}}if(fontFace&&!fontFace.includes('data:font/')){const response=await fetch(new URL('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/packages/pretendard/dist/web/variable/woff2/PretendardVariable.woff2'));if(!response.ok)throw Error('프리텐다드 폰트를 불러오지 못했습니다.');const blob=await response.blob(),data=await new Promise((r,j)=>{const reader=new FileReader();reader.onload=()=>r(reader.result);reader.onerror=j;reader.readAsDataURL(blob);});fontFace=fontFace.replace(/url\([^)]*\)/,()=> 'url("'+data+'")');}if(!fontFace)throw Error('내장 폰트를 찾을 수 없습니다. 최신 HTML 파일을 다시 열어 주세요.');const svg=drawSVG(false,bleed).replace(/(<svg[^>]*>)/,m=>m+'<style>'+fontFace+'</style>');url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('인쇄 이미지를 만들지 못했습니다. 사진을 확인해 주세요.'));img.src=url;});canvas=document.createElement('canvas');canvas.width=pw;canvas.height=ph;const ctx=canvas.getContext('2d',{willReadFrequently:true});if(!ctx)throw Error('출력용 캔버스를 만들 수 없습니다.');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,pw,ph);ctx.drawImage(image,0,0,pw,ph);const stream=new CompressionStream('deflate'),compressedPromise=new Response(stream.readable).arrayBuffer(),writer=stream.writable.getWriter();for(let y=0;y<ph;y+=64){const th=Math.min(64,ph-y),rgba=ctx.getImageData(0,y,pw,th).data;await writer.write(rgbaTileToCmyk(rgba,state.cmykColors||{}));if(y%512===0){status.textContent='CMYK PDF 변환 중… '+Math.round(y/ph*100)+'%';await new Promise(r=>setTimeout(r,0));}}await writer.close();const compressed=new Uint8Array(await compressedPromise),pdf=makeCmykPdfBytes(compressed,pw,ph,w,h,bleed);download(pdf,(state.title||'WORKUP')+'_CMYK_'+dpi+'dpi.pdf','application/pdf');status.textContent='CMYK PDF 저장 완료 · '+dpi+'dpi · '+w+' × '+h+'mm';toast('CMYK PDF를 저장했어요.');}catch(e){status.textContent=e.message||'CMYK PDF 저장에 실패했습니다.';}finally{btn.disabled=false;if(url)URL.revokeObjectURL(url);if(canvas){canvas.width=1;canvas.height=1;}}}
function validateFinishSettings(s){if(s.printSettings!==undefined){if(!s.printSettings||typeof s.printSettings!=='object'||Array.isArray(s.printSettings)||Object.entries(s.printSettings).some(([k,v])=>!['showGuides','cropMarks'].includes(k)||typeof v!=='boolean'))throw Error('재단선 설정이 올바르지 않습니다.');}if(s.numbering!==undefined){const n=s.numbering;if(!n||typeof n!=='object'||typeof n.enabled!=='boolean'||!Number.isInteger(n.start)||n.start<1||n.start>99999||!Number.isInteger(n.pad)||n.pad<1||n.pad>4||typeof n.prefix!=='string'||n.prefix.length>12||!['circle','rounded','plain'].includes(n.shape)||!['top-left','top-right','bottom-left','bottom-right'].includes(n.position)||!Number.isFinite(n.size)||n.size<3||n.size>15||!Number.isFinite(n.fontSize)||n.fontSize<4||n.fontSize>20||![n.bg,n.color].every(v=>/^#[0-9a-f]{6}$/i.test(v)))throw Error('제품 번호 설정이 올바르지 않습니다.');}if(s.cmykColors!==undefined){if(!s.cmykColors||typeof s.cmykColors!=='object'||Array.isArray(s.cmykColors)||Object.keys(s.cmykColors).length>512)throw Error('CMYK 설정이 올바르지 않습니다.');for(const [key,v] of Object.entries(s.cmykColors))if(!/^#[0-9a-f]{6}$/i.test(key)||!Array.isArray(v)||v.length!==4||v.some(n=>!Number.isFinite(n)||n<0||n>100))throw Error('CMYK 값은 0~100으로 입력해 주세요.');}for(const c of s.cells){const p=c.product;if(p.numberOverride!==undefined&&(typeof p.numberOverride!=='string'||p.numberOverride.length>20))throw Error('개별 제품 번호가 올바르지 않습니다.');if(p.numberHidden!==undefined&&typeof p.numberHidden!=='boolean')throw Error('제품 번호 표시 값이 올바르지 않습니다.');if(p.borderColor!==undefined&&!/^#[0-9a-f]{6}$/i.test(p.borderColor))throw Error('상품 테두리 색상이 올바르지 않습니다.');}}
const HELP_TOPICS=[['start','처음 시작하기'],['products','사진·상품 편집'],['layout','칸·레이아웃'],['header','상단 문구·로고'],['colors','번호·색상'],['print','저장·인쇄'],['faq','자주 묻는 질문']];
const HELP_CARDS=[
 ['start','1. 용지와 배치 고르기','왼쪽 ‘레이아웃’에서 용지 크기와 추천 배치를 고르세요. 처음에는 A3 가로·기본 상품형으로 시작하면 편합니다.','레이아웃 열기','layout'],
 ['start','2. 실제 상품 사진 넣기','가운데 상품 칸을 두 번 누르면 사진을 바꿀 수 있어요. 시작 화면의 의류 아이콘은 배치 확인용입니다. 출력 전 실제 사진으로 바꾸세요.','사진 도구 열기','images'],
 ['start','3. 상품명과 가격 입력하기','상품 칸을 누른 뒤 오른쪽에서 이름과 판매가를 입력하세요. 글자를 맞춘 후 ‘글자 크기 전체 적용’을 누르면 한 번에 통일됩니다.','상품 편집하기','product'],
 ['start','4. 상단 문구 다듬기','상단의 제목·로고·쿠폰을 누르면 각각 편집할 수 있어요. 끌어서 이동하고, 테두리의 점을 끌어 크기를 바꾸세요.','상단 편집하기','header'],
 ['start','5. 작업 저장 후 PDF 만들기','먼저 ‘작업 저장’으로 원본을 보관하세요. 이어 ‘인쇄 / PDF’에서 CMYK PDF 또는 일반 인쇄를 선택하세요.','출력 설정 열기','export'],
 ['products','사진 한 장·여러 장 넣기','한 장: 상품 칸을 두 번 누르기. 여러 장: 왼쪽 ‘사진’ → ‘상품 사진 여러 장 넣기’. 선택한 칸부터 차례로 들어갑니다.','사진 도구 열기','images'],
 ['products','사진 영역과 사진 확대의 차이','‘사진 영역 높이’는 사진이 들어갈 공간을 늘립니다. ‘사진 확대’는 그 공간 안의 사진을 키웁니다. 각각의 전체 적용 버튼으로 모든 상품에 적용할 수 있어요.','상품 크기 조절하기','product'],
 ['products','글자 크기와 판매가 전체 적용','‘글자 크기 전체 적용’은 글자 크기만 바꿉니다. ‘이 판매가를 모든 상품에 적용’은 실제 판매가를 같게 바꾸므로 확인 후 사용하세요.','상품 편집하기','product'],
 ['products','자유 이미지 추가','‘사진’ → ‘자유 이미지 추가’에서 배지·행사 이미지 등을 넣으세요. 전단 위에서 끌어 옮기고, 왼쪽에서 크기를 조절할 수 있어요.','이미지 추가 도구','images'],
 ['layout','칸 합치기·나누기','‘여러 칸 선택’을 켜고 붙어 있는 칸을 고른 뒤 ‘칸 합치기’를 누르세요. 직사각형만 합칠 수 있고, 가장 위·왼쪽 상품이 남습니다. ‘칸 나누기’로 다시 나눌 수 있어요.','레이아웃 열기','layout'],
 ['layout','줄마다 다른 칸 수·높이','왼쪽 ‘한 줄만 다르게’에서 줄 번호와 칸 수를 정하세요. 줄 높이도 조절할 수 있습니다. 두 줄 이상을 차지하는 큰 칸이 있으면 먼저 나눠 주세요.','줄 배치 조절하기','layout'],
 ['header','상단 영역 자세히 조절하기','가운데에서 원하는 영역을 누르세요. 오른쪽에서 mm 단위 위치·크기와 글자·여백·테두리를 조절할 수 있습니다. 방향키는 0.1mm, Shift와 함께 누르면 1mm 이동합니다.','상단 영역 편집','header'],
 ['header','슬로건 문구 바꾸기','왼쪽 ‘머리말’의 ‘슬로건 문구’에 직접 입력하세요. 슬로건 배경 띠를 선택한 상태에서도 오른쪽에서 문구를 바꿀 수 있어요.','슬로건 편집하기','slogan'],
 ['header','쿠폰에 이미지 넣기','머리말 원본 설정의 쿠폰 영역에서 이미지를 올리세요. ‘이미지만’ 또는 ‘이미지 + 문구’를 선택할 수 있고, 쿠폰 전체를 옮기면 안쪽 내용도 함께 움직입니다.','쿠폰 편집하기','coupon'],
 ['colors','제품 번호 넣기','왼쪽 ‘번호·색상’에서 번호 표시를 켜고 시작 번호·모양·위치를 정하세요. 특정 상품만 다른 번호를 쓰려면 상품 편집의 ‘개별 제품 번호’를 입력하세요.','번호 설정 열기','numbering'],
 ['colors','일부 영역만 색상 바꾸기','‘번호·색상’에서 글자·배경·테두리 중 적용 대상을 고르고 상단 영역을 체크하세요. 상품 칸은 ‘상품에도 적용’을 켠 뒤 선택 상품 또는 전체를 정합니다.','부분 색상 도구','colors'],
 ['colors','CMYK 코드 직접 입력','색상 칸을 누르면 피커가 열립니다. 색상판·색상 막대에서 고르거나 피커 안의 C·M·Y·K(%)와 HEX 코드를 직접 입력한 뒤 적용하세요. 화면은 RGB 미리보기입니다.','색상 도구 열기','colors'],
 ['print','작업 파일·자동 저장·지난 작업','‘작업 저장’ 파일에는 사진과 배치가 함께 담깁니다. 다른 PC에서는 ‘불러오기’로 여세요. 처음 접속하면 아이콘 화면이 나오며, 같은 브라우저의 지난 자동 저장은 ‘지난 작업 불러오기’로 복원합니다.','',''],
 ['print','재단선 보기와 PDF 재단선의 차이','작업 화면과 PDF 모두 네 모서리 재단선이 기본으로 켜져 있습니다. 왼쪽 ‘재단선 · 출력’에서 각각 끄거나 켤 수 있으며, 작업 저장·불러오기 때 이 설정도 유지됩니다. PDF에 포함한 검정 재단선은 실제 인쇄됩니다.','작업용 재단선 보기','guides'],
 ['print','CMYK PDF 저장하기','출력 설정에서 해상도를 고른 뒤 ‘CMYK PDF 저장’을 누르세요. 이미지 기반 CMYK 파일이며 인쇄소 전용 ICC 프로파일은 포함하지 않습니다. 정밀 색상은 인쇄소 교정으로 확인하세요.','PDF 설정 열기','export'],
 ['print','일반 프린터·브라우저 PDF','‘일반 인쇄 / RGB PDF’는 브라우저 인쇄 창을 엽니다. PDF 대상·배율 100%·여백 없음·배경 그래픽 켜기를 확인하세요. 재단선 포함 시 원래 용지보다 큰 종이가 필요합니다.','인쇄 설정 열기','export']
];
const HELP_FAQ=[['클릭했는데 상품 편집이 안 보여요.','여러 칸을 선택한 상태라면 한 칸만 눌러 주세요. 상단 영역을 선택했다면 상품 칸을 다시 누르면 상품 편집으로 돌아갑니다.'],['잘못 바꿨어요.','상단의 실행 취소 버튼을 누르세요. 입력 칸 밖에서는 Ctrl+Z도 사용할 수 있습니다.'],['사진이나 글자가 잘려요.','사진은 ‘전체 보이기’를 선택하거나 확대 비율을 줄이세요. 상단 문구는 영역을 키우거나 ‘자동 맞춤’을 켜세요.'],['변경했던 작업이 사라졌어요.','첫 화면은 항상 아이콘 배치입니다. 왼쪽 ‘지난 작업 불러오기’를 확인하거나 저장했던 작업 파일을 불러오세요.'],['PDF의 재단선도 실제로 인쇄되나요?','네. PDF에 포함된 재단선은 종이에 인쇄됩니다. 완성 크기 바깥 여백에 표시되며 재단하면 없어집니다. 작업 화면 보조선만 켠 경우 PDF에는 포함되지 않습니다.'],['색이 화면과 다르게 나와요.','화면은 RGB 미리보기입니다. CMYK PDF는 기본 분판 방식이며 인쇄소의 잉크·종이·ICC 환경까지 맞추려면 교정 출력이 필요합니다.']];
function renderHelp(){const query=$('helpSearch').value.trim().toLowerCase(),topic=HELP_TOPICS.find(t=>t[0]===helpTopic)||HELP_TOPICS[0];$('helpPageTitle').textContent=query?'도움말 검색 결과':topic[1];$$('[data-help-topic]').forEach(b=>b.classList.toggle('active',b.dataset.helpTopic===helpTopic&&!query));const cards=HELP_CARDS.filter(c=>query?(c[1]+' '+c[2]).toLowerCase().includes(query):c[0]===helpTopic),faq=HELP_FAQ.filter(c=>!query||(c[0]+' '+c[1]).toLowerCase().includes(query));let html='';if(!query&&helpTopic==='start')html='<div class="help-intro"><span class="eyebrow">처음이라면 이 순서대로</span><h3>왼쪽에서 고르고, 가운데를 누르고,<br>오른쪽에서 바꾸세요.</h3><div class="help-map"><div><b>① 왼쪽 도구</b><span>용지 · 배치 · 사진</span></div><div><b>② 전단 미리보기</b><span>바꿀 상품·상단 클릭</span></div><div><b>③ 오른쪽 편집</b><span>선택한 항목 세부 조절</span></div></div></div>';html+='<div class="help-card-grid">'+cards.map(c=>'<article class="guide-card"><h3>'+esc(c[1])+'</h3><p>'+esc(c[2])+'</p>'+(c[4]?'<button data-help-jump="'+c[4]+'">'+esc(c[3])+' ↗</button>':'')+'</article>').join('')+'</div>';if(helpTopic==='faq'||query)html+='<div class="help-faq">'+faq.map(c=>'<details><summary>'+esc(c[0])+'</summary><p>'+esc(c[1])+'</p></details>').join('')+'</div>';if(query&&!cards.length&&!faq.length)html='<div class="help-empty">검색 결과가 없어요.<br>‘사진’, ‘가격’, ‘슬로건’, ‘재단선’, ‘CMYK’처럼 짧게 검색해 보세요.</div>';$('helpBody').innerHTML=html;$('helpResultCount').textContent=query?(cards.length+faq.length)+'개 도움말':'';$$('[data-help-jump]').forEach(b=>b.onclick=()=>helpJump(b.dataset.helpJump));}
function openHelp(topic='start'){helpTopic=topic;$('helpSearch').value='';renderHelp();$('helpDialog').showModal();}
function helpJump(target){$('helpDialog').close();if(target==='catalog'){openCatalog();return;}if(target==='export'){$('exportBtn').onclick();return;}if(target==='slogan'){pickHeader('slogan');return;}if(target==='coupon'){pickHeader('coupon');return;}if(target==='guides'){setPrintConfig({showGuides:true});return;}if(target==='product'){choose(current().id);switchPanel('layout');return;}switchPanel(target==='header'?'header':target==='images'?'images':['numbering','colors'].includes(target)?'finish':'layout');if(target==='numbering')$('numberingSection').scrollIntoView?.({block:'start',behavior:'smooth'});if(target==='colors')$('partialColorSection').scrollIntoView?.({block:'start',behavior:'smooth'});}

function drawSVG(editing=false,bleed=false){const l=layout(),{W,H,m,header,footer}=l;let content=`<rect width="${W}" height="${H}" fill="white"/>`;if(state.header.enabled)content+=renderHeader(l,editing);for(const c of state.cells)content+=renderProduct(c,l,editing);
 if(footer)content+=svgText(state.footerText,W/2,H-m-6,Math.min(10,l.w/Math.max(state.footerText.length,1)),'#717b64','text-anchor="middle"');
 content+=renderOverlays(l,editing);if(editing)content+=workCropGuides(l);
 const off=bleed?8/state.width*W:0;if(bleed){const bleedU=3/state.width*W;let marks='';const len=4/state.width*W,gap=4/state.width*W;for(const x of [off,off+W])for(const y of [off,off+H]){const dx=x===off?-1:1,dy=y===off?-1:1;marks+=`<path d="M${x+dx*gap} ${y}h${dx*len}M${x} ${y+dy*gap}v${dy*len}" stroke="#151915" stroke-width=".5" fill="none"/>`;}return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 ${W+off*2} ${H+off*2}" width="${state.width+16}mm" height="${state.height+16}mm" font-family="Pretendard,sans-serif"><rect width="100%" height="100%" fill="white"/><rect x="${off-bleedU}" y="${off-bleedU}" width="${W+bleedU*2}" height="${H+bleedU*2}" fill="white"/><g transform="translate(${off} ${off})">${content}</g><g class="print-crop-marks">${marks}</g></svg>`;}
 return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 ${W} ${H}" width="${state.width}mm" height="${state.height}mm" font-family="Pretendard,sans-serif">${content}</svg>`;}
function renderCanvas(){$('paperCanvas').innerHTML=drawSVG(true);const l=layout();$('paperCanvas').style.height=l.H+'px';fitCanvas();bindCanvas();bindOverlayCanvas();bindHeaderCanvas();$('paperMeta').textContent=`${state.paper==='custom'?'사용자 지정':state.paper} ${state.width>=state.height?'가로':'세로'} · ${state.width} × ${state.height} mm`;$('selectionMeta').textContent=activeOverlayId?'추가 이미지 선택 · 끌어서 이동':`${selected.length}개 칸 선택 · 전체 ${state.cells.length}개 상품 칸`;$('mergeBtn').disabled=selected.length<2;$('splitBtn').disabled=!selected.length;}
function fitCanvas(){const l=layout(),el=$('canvasScroll'),g=workGuidesEnabled()?16/state.width*l.W:0;if(autoFit)zoom=Math.min((el.clientWidth-50)/(l.W+g),(el.clientHeight-45)/(l.H+g),1.4);zoom=Math.max(.12,zoom);$('paperCanvas').style.transform=`scale(${zoom})`;$('paperWrap').style.width=l.W*zoom+'px';$('paperWrap').style.height=l.H*zoom+'px';$('paperWrap').style.margin=workGuidesEnabled()?(g/2*zoom+8)+'px':'auto';$('zoomLabel').textContent=Math.round(zoom*100)+'%';}
function setValue(id,value){const el=$(id);if(document.activeElement===el)return;if(el.type==='checkbox')el.checked=!!value;else el.value=value??'';if(el.type==='color')syncCmykControl(id);}
function renderSettings(){renderPrintSettings();for(const [id,key] of Object.entries({projectTitle:'title',paper:'paper',paperW:'width',paperH:'height',cols:'cols',rows:'rows',accent:'accent',margin:'margin',showLines:'showLines',showFooter:'showFooter',footerText:'footerText',gutter:'gutter'}))setValue(id,state[key]);for(const [id,key] of Object.entries({showHeader:'enabled',headerHeight:'height',headline:'headline',highlight:'highlight',subtitle:'subtitle',brand:'brand',brandSub:'brandSub',sloganText:'sloganText',couponEnabled:'coupon',couponTitle:'couponTitle',couponText:'couponText'}))setValue(id,key==='sloganText'?(state.header[key]??'EVERY WORKER, EVERY WEAR.'):state.header[key]);$$('[data-template]').forEach(b=>b.classList.toggle('active',b.dataset.template===state.templateId));syncRowControl();}
function dpi(c){if(!c.product.image)return null;const p=c.product,img=p.image,box=productMetrics(c).photo,r=p.imageFit==='cover'?Math.max(box.w/img.width,box.h/img.height):Math.min(box.w/img.width,box.h/img.height);return Math.round(25.4/(r*state.width/1200*p.imageScale/100));}
function renderInspector(){$('headerRegionForm').classList.toggle('hidden',!activeHeaderKey);$('inspectorTitle').textContent=activeHeaderKey?'상단 영역 편집':'상품 편집';if(activeHeaderKey){$('productForm').classList.add('hidden');$('selectionSummary').classList.add('hidden');$('cellTag').textContent=headerPart(activeHeaderKey)?.label||'';renderHeaderInspector();return;}const c=current();if(!c)return;const p=c.product;$('cellTag').textContent=String(state.cells.indexOf(c)+1).padStart(2,'0');$('productForm').classList.toggle('hidden',selected.length>1);$('selectionSummary').classList.toggle('hidden',selected.length===1);$('selectionSummary').textContent=`${selected.length}개 칸을 선택했어요. 위쪽 도구에서 칸을 합치거나 나눌 수 있습니다. 합치면 가장 위·왼쪽 상품 내용이 남습니다.`;for(const [id,key] of Object.entries({productName:'name',price:'price',unit:'unit',originalPrice:'originalPrice',description:'description',badge:'badge',nameSize:'nameSize',priceSize:'priceSize',imageScale:'imageScale',imageX:'imageX',imageY:'imageY',imageFit:'imageFit',photoArea:'photoArea',detailSize:'detailSize',cellBg:'bg',cellColor:'color',featured:'featured'}))setValue(id,id==='price'||id==='originalPrice'?money(p[key]):key==='photoArea'?(p[key]??65):key==='detailSize'?(p[key]??11):p[key]);$('photoAreaValue').textContent=(p.photoArea??65)+'%';$('scaleValue').textContent=p.imageScale+'%';$('singlePhoto').innerHTML=p.image?`<img src="${esc(p.image.data)}" alt="선택한 상품 사진">`:p.sample?sampleArt(p.sample,p.sampleColor):'<span>사진을 추가해 주세요</span>';const d=dpi(c),res=$('resolution');res.className='resolution'+(d&&d<150?' bad':d&&d<300?' warn':'');res.textContent=d?`${p.image.width} × ${p.image.height}px · 인쇄 약 ${d}dpi${d<150?' / 더 큰 원본 권장':d<300?' / 300dpi 이상 원본 권장':' / 선명한 인쇄에 적합'}`:p.sample?'배치 확인용 샘플 · 실제 상품 사진으로 교체해 주세요.':'투명 배경 PNG를 추천합니다.';renderLibrary();renderNumberingUI();syncAllCmyk();}
function renderLibrary(){const images=state.cells.filter(c=>c.product.image);$('imageLibrary').innerHTML=images.map(c=>`<button data-use-image="${c.id}" title="선택한 칸에 이 사진 적용"><img src="${esc(c.product.image.data)}" alt="${esc(c.product.name)}"><small>${state.cells.indexOf(c)+1}</small></button>`).join('');$$('[data-use-image]').forEach(btn=>btn.onclick=()=>{const source=state.cells.find(c=>c.id===btn.dataset.useImage);mutate(()=>{current().product.image=clone(source.product.image);current().product.sample=null;});toast('선택한 칸에 사진을 적용했어요.');});}
function render(){ensureSelection();renderSettings();renderCanvas();renderInspector();renderOverlayUI();renderHeaderPositionUI();renderNumberingUI();syncAllCmyk();updateHistory();}
function choose(id,add=false){activeHeaderKey=null;activeOverlayId=null;renderOverlayUI();if(add){selected=selected.includes(id)?selected.filter(v=>v!==id):[...selected,id];if(!selected.length)selected=[id];}else selected=[id];renderCanvas();renderInspector();}
function bindCanvas(){$$('.product-cell').forEach(el=>{el.addEventListener('click',e=>choose(el.dataset.id,e.shiftKey||multi));el.addEventListener('dblclick',()=>{choose(el.dataset.id);$('photoUpload').click();});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(el.dataset.id,e.shiftKey||multi);}});el.addEventListener('pointerdown',e=>{if(multi||e.shiftKey||e.button!==0)return;const sx=e.clientX,sy=e.clientY;let started=false;const move=ev=>{if(Math.hypot(ev.clientX-sx,ev.clientY-sy)>8){started=true;dragId=el.dataset.id;$('paperCanvas').style.cursor='grabbing';}};const up=ev=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);$('paperCanvas').style.cursor='';if(!started)return;const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('.product-cell');if(target&&target.dataset.id!==dragId){const a=state.cells.find(c=>c.id===dragId),b=state.cells.find(c=>c.id===target.dataset.id);mutate(()=>{[a.product,b.product]=[b.product,a.product];selected=[b.id];});toast('상품 위치를 바꿨어요.');}dragId=null;};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);});el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drag-over');});el.addEventListener('dragleave',()=>el.classList.remove('drag-over'));el.addEventListener('drop',async e=>{e.preventDefault();choose(el.dataset.id);await uploadBatch(e.dataTransfer.files);});});}
function switchPanel(panel){currentPanel=panel;if(panel==='header'){activeHeaderKey||='headline';activeOverlayId=null;}else if(panel!=='finish')activeHeaderKey=null;$$('[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));$$('.panel').forEach(p=>p.classList.toggle('hidden',p.id!=='panel-'+panel));renderInspector();renderCanvas();}
renderTemplateList();
