$('resumeProject').onclick=()=>{if(!resumeState)return;if(state.cells.some(c=>hasCustomContent(c.product))&&!confirm('현재 편집 내용 대신 지난 작업을 불러올까요?'))return;mutate(()=>{state=clone(resumeState);selected=[state.cells[0].id];autoFit=true;});toast('이전에 자동 저장된 작업을 불러왔어요.');};
$('newProject').onclick=()=>{if(state.cells.some(c=>hasCustomContent(c.product))&&!confirm('현재 작업을 아이콘 기본 화면으로 바꿀까요? 실행 취소로 되돌릴 수 있습니다.'))return;mutate(()=>{state=clone(DEFAULT_STATE);selected=[state.cells[0].id];autoFit=true;});toast('상품 아이콘이 배치된 기본 화면으로 돌아왔어요.');};
