const headerBindings={showHeader:'enabled',headerHeight:'height',headline:'headline',highlight:'highlight',subtitle:'subtitle',brand:'brand',brandSub:'brandSub',sloganText:'sloganText',couponEnabled:'coupon',couponTitle:'couponTitle',couponText:'couponText'};
for(const [id,key] of Object.entries(headerBindings))$(id).addEventListener('input',e=>{state.header[key]=e.target.type==='checkbox'?e.target.checked:e.target.type==='range'?Number(e.target.value):e.target.value;renderCanvas();queueSave();});
const productBindings={productName:'name',price:'price',unit:'unit',originalPrice:'originalPrice',description:'description',badge:'badge',nameSize:'nameSize',priceSize:'priceSize',imageScale:'imageScale',imageX:'imageX',imageY:'imageY',imageFit:'imageFit',photoArea:'photoArea',detailSize:'detailSize',cellBg:'bg',cellColor:'color',featured:'featured'};
for(const [id,key] of Object.entries(productBindings))$(id).addEventListener('input',e=>{const p=current().product,v=e.target.value;p[key]=e.target.type==='checkbox'?e.target.checked:['number','range'].includes(e.target.type)?clamp(v,Number(e.target.min),Number(e.target.max)):['price','originalPrice'].includes(key)?v.replace(/\D/g,'').slice(0,12):v;renderCanvas();if(id==='photoArea')$('photoAreaValue').textContent=p.photoArea+'%';if(id==='imageScale'){$('scaleValue').textContent=p.imageScale+'%';renderInspector();}queueSave();});
