$('mergeBtn').onclick=()=>{try{const chosen=state.cells.filter(c=>selected.includes(c.id));const lost=chosen.sort((a,b)=>a.y-b.y||a.x-b.x).slice(1).filter(c=>c.product.image||c.product.name);if(lost.length&&!confirm(`선택한 ${selected.length}개 칸을 합칩니다. 가장 위·왼쪽 상품을 남기고 나머지 ${lost.length}개 상품 내용이 지워집니다. 계속할까요?`))return;const before=clone(state);const c=mergeCellsIn(before,selected);mutate(()=>{state=before;state.templateId="";selected=[c.id];});toast('칸을 합쳤어요. ‘실행 취소’로 되돌릴 수 있어요.');}catch(e){toast(e.message);}};
$('splitBtn').onclick=()=>$('splitDialog').showModal();
$('doSplit').onclick=()=>{const cols=clamp(Math.round($('splitCols').value),1,12),rows=clamp(Math.round($('splitRows').value),1,12);if(cols*rows===1){toast('가로 또는 세로를 2칸 이상으로 설정해 주세요.');return;}if(state.cells.length+selected.length*(cols*rows-1)>144){toast('전단 한 장에는 최대 144개 칸을 만들 수 있어요.');return;}mutate(()=>{const result=[],newIds=[];for(const c of state.cells){if(!selected.includes(c.id)){result.push(c);continue;}for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const id=uid();result.push({id,x:c.x+x*c.w/cols,y:c.y+y*c.h/rows,w:c.w/cols,h:c.h/rows,product:x===0&&y===0?clone(c.product):product(0,true)});newIds.push(id);}}state.cells=result.sort((a,b)=>a.y-b.y||a.x-b.x);state.templateId="";selected=[newIds[0]];});$('splitDialog').close();toast('선택한 칸을 원하는 수로 나눴어요.');};
$('applyRow').onclick=()=>{const row=clamp(Math.round($('targetRow').value),1,state.rows)-1,count=clamp(Math.round($('rowCount').value),1,12),eps=0.000001,bands=rowBands(),y0=bands[row],rh=bands[row+1]-y0;const affected=state.cells.filter(c=>c.y<y0+rh-eps&&c.y+c.h>y0+eps);if(affected.some(c=>Math.abs(c.y-y0)>eps||Math.abs(c.h-rh)>eps)){toast('이 줄에는 여러 줄을 차지하는 칸이 있어요. 해당 칸을 먼저 나눠 주세요.');return;}const old=affected.sort((a,b)=>a.x-b.x).map(c=>clone(c.product));if(state.cells.length-old.length+count>144){toast('최대 144개 칸까지 만들 수 있어요.');return;}if(old.length>count&&old.slice(count).some(p=>p.image||p.name)&&!confirm('줄의 칸 수를 줄이면 뒤쪽 상품이 빠집니다. 계속할까요?'))return;mutate(()=>{state.cells=state.cells.filter(c=>!affected.includes(c));const added=Array.from({length:count},(_,i)=>({id:uid(),x:i*state.cols/count,y:y0,w:state.cols/count,h:rh,product:old[i]||product(i)}));state.cells.push(...added);state.templateId='';state.cells.sort((a,b)=>a.y-b.y||a.x-b.x);selected=[added[0].id];});toast((row+1)+'번째 줄을 '+count+'칸으로 바꿨어요.');};
