async function readImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('PNG, JPG, WEBP 파일을 사용해 주세요.');if(file.size>20*1024*1024)throw Error('사진 한 장은 20MB 이하로 넣어 주세요.');const data=await new Promise((r,j)=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.onerror=j;fr.readAsDataURL(file);});const img=await new Promise((r,j)=>{const i=new Image();i.onload=()=>r(i);i.onerror=()=>j(Error('사진을 읽을 수 없습니다.'));i.src=data;});if(img.width*img.height>120000000)throw Error('이미지 크기가 너무 큽니다. 1억 2천만 픽셀 이하로 줄여 주세요.');return {data,width:img.width,height:img.height,filename:file.name};}
async function uploadBatch(files){try{const start=state.cells.indexOf(current()),list=Array.from(files);if(!list.length)return;const available=state.cells.length-start;if(list.length>available){toast(`남은 ${available}개 칸까지만 사진을 넣습니다.`);}const assets=[];for(const f of list.slice(0,available))assets.push(await readImage(f));mutate(()=>assets.forEach((img,i)=>{const p=state.cells[start+i].product;p.image=img;p.sample=null;p.imageScale=100;p.imageX=p.imageY=0;}));toast(`${assets.length}개 상품 사진을 넣었어요.`);}catch(e){toast(e.message||'사진을 넣지 못했어요.');}}
