function validateProject(s){if(!s||s.version!==1||!Array.isArray(s.cells)||!s.cells.length||s.cells.length>144||!s.header)throw Error('워크업 전단 작업 파일이 아닙니다.');if(!Number.isInteger(s.cols)||!Number.isInteger(s.rows)||s.cols<1||s.cols>12||s.rows<1||s.rows>12||!Number.isFinite(s.width)||s.width<80||s.width>1000||!Number.isFinite(s.height)||s.height<80||s.height>1000)throw Error('용지 또는 격자 크기가 올바르지 않습니다.');if(s.rowSizes!==undefined&&(!Array.isArray(s.rowSizes)||s.rowSizes.length!==s.rows||s.rowSizes.some(v=>!Number.isFinite(v)||v<=0)||Math.abs(s.rowSizes.reduce((a,b)=>a+b,0)-s.rows)>0.000001))throw Error('줄 높이 정보가 올바르지 않습니다.');if(s.gutter!==undefined&&(!Number.isFinite(s.gutter)||s.gutter<0||s.gutter>8))throw Error('칸 간격이 올바르지 않습니다.');if(s.globalProductStyle!==undefined){if(!s.globalProductStyle||typeof s.globalProductStyle!=='object'||Array.isArray(s.globalProductStyle))throw Error('전체 적용 설정이 올바르지 않습니다.');const ranges={nameSize:[9,40],priceSize:[14,80],detailSize:[7,24],photoArea:[35,85],imageScale:[40,250]};for(const [k,v] of Object.entries(s.globalProductStyle)){if(!Object.prototype.hasOwnProperty.call(ranges,k)||!Number.isFinite(v)||v<ranges[k][0]||v>ranges[k][1])throw Error('전체 적용 설정이 올바르지 않습니다.');}}const placed=[],ids=new Set();let totalArea=0;const isImg=i=>i===null||(i&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(i.data)&&Number.isFinite(i.width)&&i.width>0&&Number.isFinite(i.height)&&i.height>0);const str=(v,n=500)=>typeof v==='string'&&v.length<=n;for(const k of ['title','footerText','accent'])if(!str(s[k]))throw Error('파일의 문구가 올바르지 않습니다.');if(!/^#[0-9a-f]{6}$/i.test(s.accent)||!Number.isFinite(s.margin)||s.margin<3||s.margin>20)throw Error('전단 스타일이 올바르지 않습니다.');for(const k of ['enabled','coupon'])if(typeof s.header[k]!=='boolean')throw Error('머리말 정보가 올바르지 않습니다.');if(!Number.isFinite(s.header.height)||s.header.height<10||s.header.height>32||!isImg(s.header.logo))throw Error('머리말 정보가 올바르지 않습니다.');for(const k of ['headline','highlight','subtitle','brand','brandSub','couponTitle','couponText'])if(!str(s.header[k]))throw Error('머리말 문구가 올바르지 않습니다.');if(s.header.couponImage!==undefined&&!isImg(s.header.couponImage))throw Error('쿠폰 이미지가 올바르지 않습니다.');if(s.header.couponImageMode!==undefined&&!['replace','withText'].includes(s.header.couponImageMode))throw Error('쿠폰 표시 방식이 올바르지 않습니다.');if(s.header.couponImageFit!==undefined&&!['contain','cover'].includes(s.header.couponImageFit))throw Error('쿠폰 이미지 맞춤이 올바르지 않습니다.');if(s.header.positions!==undefined){if(!s.header.positions||typeof s.header.positions!=='object'||Array.isArray(s.header.positions))throw Error('문구 위치가 올바르지 않습니다.');for(const [k,p] of Object.entries(s.header.positions)){if(!['headline','highlight','subtitle','brandSub','couponTitle','couponText'].includes(k)||!p||!Number.isFinite(p.x)||Math.abs(p.x)>50||!Number.isFinite(p.y)||Math.abs(p.y)>30||!['left','center','right'].includes(p.align))throw Error('문구 위치가 올바르지 않습니다.');}}if(s.overlays!==undefined){if(!Array.isArray(s.overlays)||s.overlays.length>20)throw Error('추가 이미지 개수가 올바르지 않습니다.');const seen=new Set();for(const o of s.overlays){if(!o||!str(o.id,100)||!/^[a-zA-Z0-9_-]+$/.test(o.id)||seen.has(o.id)||!isImg(o.image)||!o.image||!['x','y','width','height'].every(k=>Number.isFinite(o[k]))||o.x<0||o.y<0||o.width<=0||o.height<=0||o.width>100||o.height>100||o.x+o.width>100.000001||o.y+o.height>100.000001)throw Error('추가 이미지 정보가 올바르지 않습니다.');seen.add(o.id);}}validateFinishSettings(s);validateHeaderRegions(s.header);for(const c of s.cells){if(!str(c.id,100)||!/^[a-zA-Z0-9_-]+$/.test(c.id)||ids.has(c.id)||!['x','y','w','h'].every(k=>Number.isFinite(c[k]))||c.x<0||c.y<0||c.w<0.001||c.h<0.001||c.x+c.w>s.cols+0.000001||c.y+c.h>s.rows+0.000001||!c.product||!isImg(c.product.image))throw Error('상품 칸 정보가 올바르지 않습니다.');ids.add(c.id);const p=c.product;for(const k of ['name','price','unit','originalPrice','description','badge','bg','color'])if(!str(p[k],200))throw Error('상품 정보가 올바르지 않습니다.');for(const [k,min,max] of [['nameSize',9,40],['priceSize',14,80],['imageScale',40,250],['imageX',-35,35],['imageY',-35,35]])if(!Number.isFinite(p[k])||p[k]<min||p[k]>max)throw Error('상품 크기 정보가 올바르지 않습니다.');if(p.photoArea!==undefined&&(!Number.isFinite(p.photoArea)||p.photoArea<35||p.photoArea>85))throw Error('사진 영역 크기가 올바르지 않습니다.');if(p.detailSize!==undefined&&(!Number.isFinite(p.detailSize)||p.detailSize<7||p.detailSize>24))throw Error('설명 글자 크기가 올바르지 않습니다.');if(!['contain','cover'].includes(p.imageFit)||!/^#[0-9a-f]{6}$/i.test(p.bg)||!/^#[0-9a-f]{6}$/i.test(p.color))throw Error('상품 스타일이 올바르지 않습니다.');for(const prior of placed){const ow=Math.min(c.x+c.w,prior.x+prior.w)-Math.max(c.x,prior.x),oh=Math.min(c.y+c.h,prior.y+prior.h)-Math.max(c.y,prior.y);if(ow>0.000001&&oh>0.000001)throw Error('겹치는 칸이 있습니다.');}placed.push(c);totalArea+=c.w*c.h;}if(Math.abs(totalArea-s.cols*s.rows)>0.000001)throw Error('비어 있는 격자가 있습니다.');return true;}
$('projectFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>250*1024*1024)throw Error('작업 파일은 250MB 이하로 불러올 수 있어요.');const next=JSON.parse(await f.text());validateProject(next);if(confirm('현재 작업을 불러온 파일로 바꿀까요? 저장하지 않은 내용은 실행 취소로 복구할 수 있습니다.'))mutate(()=>{state=next;selected=[state.cells[0].id];autoFit=true;});toast('작업 파일을 불러왔어요.');}catch(err){toast(err instanceof SyntaxError?'JSON 작업 파일을 확인해 주세요.':err.message);}e.target.value='';};
